import re, collections, math

def parse_demo(text):
    # extract input and output blocks, line numeric arrays between headers
    inp_m=re.search(r'Demo pair \d+ input \(\d+x\d+\):\n((?:[0-9 ]+\n)+)', text)
    out_m=re.search(r'Demo pair \d+ output \(\d+x\d+\):\n((?:[0-9 ]+\n?)+)', text)
    if not inp_m or not out_m: raise ValueError((bool(inp_m),bool(out_m)))
    togrid=lambda s:[[int(x) for x in line.split()] for line in s.strip().splitlines()]
    return togrid(inp_m.group(1)),togrid(out_m.group(1))

def transform(grid):
    freq=collections.Counter(v for row in grid for v in row)
    common=[c for c,_ in freq.most_common(2)]
    background=freq.most_common(1)[0][0]
    special={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in common}
    if not special: return [[background]]
    rs=sorted({r for r,c in special}); cs=sorted({c for r,c in special})
    def gcd_steps(vals):
        g=0
        for d in (b-a for a,b in zip(vals,vals[1:])): g=math.gcd(g,d)
        return g or 1
    dr=gcd_steps(rs); dc=gcd_steps(cs)
    rows=list(range(rs[0],rs[-1]+1,dr)); cols=list(range(cs[0],cs[-1]+1,dc))
    out=[]
    for r1,r2 in zip(rows,rows[1:]):
        line=[]
        for c1,c2 in zip(cols,cols[1:]):
            vals=[grid[r1][c1],grid[r1][c2],grid[r2][c1],grid[r2][c2]]
            if vals[0]==vals[1]==vals[2]==vals[3] and vals[0] not in common:
                line.append(vals[0])
            else: line.append(background)
        out.append(line)
    return out

